algorithm CountVowels
    define word as string;
    define i as integer;
    define counter as integer;
    define letter as character;
    read word;
    counter <- 0;
    for i <- 0 to length(word) - 1 step 1 do
        letter <- charAt(word, i);
        if letter = 'a' or letter = 'e' or letter = 'i' or letter = 'o' or letter = 'u' then
            counter <- counter + 1;
        endIf
    endFor
    write counter;
endAlgorithm
